// Generated by Suite Builder from a crawl of the site. The suite's rules, checked before every run.
// EDIT RULES: OFF LIMITS, to people and AIs alike. This file is one of the suite's rules (SUITE-RULES.md). A change to it, a move, a rename or a deletion is a change outside a YOURS block: regenerating will overwrite it, SR-16 reports it and suite verify finds it. To get a test through, fix the test or push back on the story; to change a rule, change Suite Builder.
// The suite's rules (SUITE-RULES.md), checked before Cypress starts: `npm test` runs this first, and
// the tests run whatever it says (G-119). Plain Node, no browser, no packages. `npm run rules` alone.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { basename, join, relative } from 'node:path';

const RULES = {
  'SR-01': 'A story is in cypress/e2e/cases/',
  'SR-04': 'A story\'s file is named after its id',
  'SR-05': 'Each story id is used once',
  'SR-06': 'A story is one test',
  'SR-07': 'A story has one check',
  'SR-08': 'The check comes last',
  'SR-10': 'A story uses page objects, not Cypress',
  'SR-11': 'A story does not assert',
  'SR-12': 'Nothing sleeps',
  'SR-13': 'No regular expressions in tests and pages',
  'SR-14': 'A test switched off says why',
  'SR-15': 'YOURS blocks keep both marker lines',
  'SR-16': 'Generated files change only inside YOURS blocks',
  'SR-17': 'Every story in stories/done/ has its test',
  'SR-18': 'Every story test has its story in stories/done/',
  'SR-19': 'Every test checks something',
  'SR-20': 'Account files stay out of git',
  'SR-21': 'A done story\'s notes name every criterion, by its number',
  'SR-22': 'One element, one name',
};
// How each rule is held (G-119): hard and story fail the check; advisory is a warning, and the run goes on.
const TIERS = {
  'SR-01': 'story',
  'SR-04': 'story',
  'SR-05': 'story',
  'SR-06': 'advisory',
  'SR-07': 'advisory',
  'SR-08': 'advisory',
  'SR-10': 'story',
  'SR-11': 'advisory',
  'SR-12': 'advisory',
  'SR-13': 'advisory',
  'SR-14': 'advisory',
  'SR-15': 'hard',
  'SR-16': 'hard',
  'SR-17': 'story',
  'SR-18': 'story',
  'SR-19': 'hard',
  'SR-20': 'hard',
  'SR-21': 'story',
  'SR-22': 'hard',
};
const FINGERPRINTS = 'suite-rules/fingerprints.txt';
// Generated files a team may delete for good (the pipelines it does not use, the container files).
const DELETABLE = [".github/workflows/suite.yml",".gitlab-ci.yml","azure-pipelines.yml","Dockerfile",".dockerignore",".github/workflows/stories.yml","azure-stories.yml"];
const root = process.cwd();
const problems = [];
const add = (id, text) => problems.push(`[${id} ${RULES[id]}] ${text}`);
// Marks an SR-16 finding on guidance text: held as advisory (G-184).
const ADVISORY = '(advisory) ';

function files(dir) {
  if (!existsSync(join(root, dir))) return [];
  return readdirSync(join(root, dir)).flatMap((name) => {
    const path = join(dir, name);
    return statSync(join(root, path)).isDirectory() ? files(path) : [path.split('\\').join('/')];
  });
}
const read = (path) => readFileSync(join(root, path), 'utf8').replace(/\r\n/g, '\n');

// ---- SR-15 and SR-16: YOURS blocks, and generated files as generated -------------------------------

function marker(line, end) {
  let t = line.trim();
  if (t.startsWith('//')) t = t.slice(2);
  else if (t.startsWith('<!--')) t = t.slice(4);
  else if (t.startsWith('#')) t = t.slice(1);
  else return false;
  t = t.replace(/^[ \t]+/, '');
  const word = end ? 'END YOURS (' : 'YOURS (';
  return t.startsWith(`==== ${word}`) || t.startsWith(`---- ${word}`);
}

function outsideYours(text) {
  const out = [];
  let inside = false;
  for (const line of text.split('\n')) {
    if (inside) {
      if (marker(line, true)) {
        inside = false;
        out.push(line);
      }
      continue;
    }
    out.push(line);
    if (marker(line, false)) inside = true;
  }
  return out.join('\n');
}

const fingerprints = new Map();
if (existsSync(join(root, FINGERPRINTS))) {
  for (const row of read(FINGERPRINTS).split('\n')) {
    const gap = row.indexOf('  ');
    if (!row.startsWith('#') && gap > 0) fingerprints.set(row.slice(gap + 2).trim(), row.slice(0, gap));
  }
} else {
  add('SR-16', `${FINGERPRINTS} is missing: rebuild the suite (suite build <project>) to put it back.`);
}
for (const [path, print] of fingerprints) {
  if (!existsSync(join(root, path))) {
    if (!DELETABLE.includes(path)) add('SR-16', `${path}: generated, and deleted. suite build <project> puts it back.`);
    continue;
  }
  const text = read(path);
  const opens = text.split('\n').filter((l) => marker(l, false)).length;
  const closes = text.split('\n').filter((l) => marker(l, true)).length;
  if (opens !== closes) add('SR-15', `${path}: a YOURS block lost a marker line (${opens} opening, ${closes} closing).`);
  else if (createHash('sha256').update(outsideYours(text), 'utf8').digest('hex') !== print) {
    // Guidance text (a Markdown file that is no rule) changed is a warning, not a failure (G-184).
    if (path.endsWith('.md') && path !== 'SUITE-RULES.md') add('SR-16', `${ADVISORY}${path}: changed outside its YOURS blocks. It is the suite's own guidance text (no code, no rule), so the change stands and the run goes on; regenerating rewrites it, so a change worth keeping goes into Suite Builder too.`);
    else add('SR-16', `${path}: changed outside its YOURS blocks. Move the change into a YOURS block; suite build <project> puts the rest back.`);
  }
}

// ---- the tests ---------------------------------------------------------------------------------------

const specs = files('cypress/e2e').filter((f) => f.endsWith('.cy.ts') || f.endsWith('.cy.js'));
// A story is a spec that calls story(): a spec of your own with plain it() tests is held to the hard rules only.
const isStory = (f) => /\bstory\(\s*['"`]/.test(read(f));
for (const f of specs) {
  if (!f.startsWith('cypress/e2e/cases/') && f !== 'cypress/e2e/harness.cy.ts' && isStory(f)) add('SR-01', `${f}: stories go in cypress/e2e/cases/.`);
}

/** Code without comments and string contents, so words inside them don't count. */
function code(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '/' && text[i + 1] === '/') {
      while (i < text.length && text[i] !== '\n') i++;
      out += '\n';
    } else if (c === '/' && text[i + 1] === '*') {
      i += 2;
      while (i < text.length && !(text[i] === '*' && text[i + 1] === '/')) i++;
      i++;
    } else if (c === "'" || c === '"' || c === '`') {
      out += c;
      i++;
      while (i < text.length && text[i] !== c) i += text[i] === '\\' ? 2 : 1;
      out += c;
    } else out += c;
  }
  return out;
}
const count = (text, what) => text.split(what).length - 1;
const lineOf = (text, what) => text.slice(0, text.indexOf(what)).split('\n').length;

const stories = specs.filter((f) => f.startsWith('cypress/e2e/cases/') && !fingerprints.has(f) && isStory(f));
const storyIds = new Map();
for (const f of stories) {
  const text = read(f);
  const bare = code(text);
  const call = /\bstory\(\s*(['"`])([^'"`]+)\1\s*,\s*(['"`])/.exec(text);
  if (call) {
    const id = call[2];
    if (basename(f).replace(/\.cy\.[jt]s$/, '') !== id.toLowerCase()) add('SR-04', `${f}: story ${id} goes in ${id.toLowerCase()}.cy.ts.`);
    if (storyIds.has(id.toLowerCase())) add('SR-05', `${f}: story ${id} already has a test (${storyIds.get(id.toLowerCase())}).`);
    else storyIds.set(id.toLowerCase(), f);
  }
  if (count(bare, 'story(') > 1 || /\b(it|describe|context|specify)(\.\w+)?\s*\(/.test(bare)) add('SR-06', `${f}: one story(), and no it() or describe() of its own.`);
  const verifies = count(bare, '.verify()');
  if (verifies !== 1) add('SR-07', `${f}: a story has one check, one .verify() at the end of its chain; it has ${verifies}.`);
  else {
    const after = bare.slice(bare.indexOf('.verify()'));
    const next = after.indexOf(';');
    if (/\.(click|enter|check|uncheck|clear|execute|navigateTo|read)\(\)/.test(next < 0 ? after : after.slice(next))) {
      add('SR-08', `${f}: a step comes after the check. Move it before .verify(), or make it a story of its own.`);
    }
  }
  for (const what of ['cy.', 'Cypress.', 'Find.', 'UserActions.']) {
    if (bare.includes(what)) add('SR-10', `${f}:${lineOf(bare, what)}: ${what} in a story; use page objects: add the element to the page's Elements and an action or check that uses it.`);
  }
  for (const what of ['expect(', 'assert.', 'assert(', '.should(']) {
    if (bare.includes(what)) add('SR-11', `${f}:${lineOf(bare, what)}: ${what} in a story; checks live in the page's verify(), and the story ends with one.`);
  }
}

const tests = [...specs, ...files('cypress/support/pages')];
for (const f of tests) {
  const bare = code(read(f));
  if (/cy\.wait\(\s*\d/.test(bare)) add('SR-12', `${f}:${lineOf(bare, 'cy.wait(')}: a sleep; wait for what the step needs with WaitActions.`);
  if (f !== 'cypress/e2e/harness.cy.ts' && (bare.includes('RegExp') || /[=(,:]\s*\/[^/*\s][^/\n]*\/[gimsuy]*[.,;)\s]/.test(bare))) {
    add('SR-13', `${f}: a regular expression; compare plain strings (Checks), or move it into support/core/.`);
  }
  // A test switched off says why, in a comment on its line; .only switches off every other test.
  const raw = read(f).split('\n');
  bare.split('\n').forEach((line, i) => {
    for (const what of ['.skip(', '.only(', 'xit(', 'xdescribe(']) {
      if (!line.includes(what)) continue;
      const why = (raw[i] ?? '').split('//').slice(1).join('//').trim();
      if (what === '.only(') add('SR-14', `${f}:${i + 1}: .only( switches off every other test.`);
      else if (!why) add('SR-14', `${f}:${i + 1}: ${what} switches a test off without saying why: say it in a comment on the line.`);
    }
  });
}
for (const f of specs.filter((s) => s.startsWith('cypress/e2e/cases/'))) {
  const bare = code(read(f));
  const bodies = bare.split(/\b(?:it|story)\s*\(/).slice(1);
  bodies.forEach((body, i) => {
    // Checks.assume is not a check: it skips a test whose data is not there, and checks nothing of the site.
    const checks = body.replaceAll('Checks.assume(', 'assume(');
    if (!checks.includes('.verify()') && !checks.includes('Checks.')) add('SR-19', `${f}: test ${i + 1} checks nothing; end it with .verify()... or a Checks call.`);
  });
}

// ---- SR-20: account files stay out of git (G-159) ------------------------------------------------

const ignored = existsSync('.gitignore') ? read('.gitignore').split(/\r?\n/).map((l) => l.trim()) : [];
if (!ignored.some((l) => l === 'secrets/*.login' || l === '/secrets/*.login' || l === 'secrets/')) {
  add('SR-20', '.gitignore does not leave out secrets/*.login, so an account file could be committed. Put the line secrets/*.login back in .gitignore.');
}
const tracked = spawnSync('git', ['ls-files', '--', 'secrets'], { encoding: 'utf8' });
for (const file of tracked.status === 0 ? tracked.stdout.split('\n').filter(Boolean) : []) {
  if (!file.endsWith('README.md')) add('SR-20', `${file} is committed: an account in git is an account everyone with the repository has. Run git rm --cached ${file}, then change that account's password.`);
}

// ---- SR-17 and SR-18: stories/done/ and the story tests, both ways ---------------------------------

function storyId(text, fileName) {
  const base = fileName.replace(/\.[^.]+$/, '');
  const first = (s) => /(?<![A-Za-z0-9])[A-Za-z]+-\d+(?![A-Za-z])/.exec(s)?.[0] ?? null;
  const notes = text.indexOf('\n----');
  return first(base) ?? first(text.startsWith('----') ? '' : notes >= 0 ? text.slice(0, notes) : text) ?? base.trim().split(/\s+/)[0];
}
const done = new Map();
const doneTexts = new Map();
for (const f of files('stories/done')) {
  const name = basename(f);
  if (name.startsWith('.') || name.toLowerCase() === 'readme.md') continue;
  const id = storyId(read(f), name).toLowerCase();
  done.set(id, name);
  doneTexts.set(id, read(f));
}
// A requirement, the story's n-th acceptance criterion (proj-1-3), belongs to its story (G-188).
const storyOf = (id) => /^(.*\d)-(\d+)$/.exec(id)?.[1] ?? id;
const tested = new Set([...storyIds.keys()].map(storyOf));
for (const [id, f] of storyIds) if (!done.has(storyOf(id))) add('SR-18', `${f}: story ${storyOf(id).toUpperCase()} has no story file in stories/done/.`);
for (const [id, name] of done) if (!tested.has(id)) add('SR-17', `stories/done/${name}: no story test says story('${id.toUpperCase()}', ...) or story('${id.toUpperCase()}-<n>', ...) for one of its requirements.`);

// ---- SR-21: a done story's notes name every criterion, each by the number it was given ------------

const LIST_ITEM = /^([-*\u2022]|\d{1,2}[.)])\s+\S/;
/** How many acceptance criteria a story lists: the list under its line naming them, above any "----" note; 0 with none. */
function criteriaCount(text) {
  const notes = text.indexOf('\n----');
  const story = text.startsWith('----') ? '' : notes >= 0 ? text.slice(0, notes) : text;
  let count = 0;
  let under = false;
  for (const line of story.split(/\r?\n/)) {
    const t = line.trim();
    if (!under) {
      under = /criteri/i.test(t) && !LIST_ITEM.test(t);
      continue;
    }
    if (LIST_ITEM.test(t)) count++;
    else if (t && count > 0) break;
  }
  return count;
}
/** The criterion numbers a story's notes name: a test (<id>-<n>), or a Not implemented line (<n> <the criterion>: ...). */
function namedCriteria(text, id) {
  const named = new Set();
  const notes = text.indexOf('\n----');
  if (notes < 0) return named;
  const all = text.slice(notes);
  const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  for (const m of all.matchAll(new RegExp(`(?<![A-Za-z0-9])${escaped}-(\\d{1,3})(?!\\d)`, 'gi'))) named.add(Number(m[1]));
  let listing = false;
  for (const line of all.split(/\r?\n/)) {
    let t = line.trim();
    if (/^not implemented:/i.test(t)) {
      listing = true;
      t = t.slice(16).trim();
    } else if (t.startsWith('----') || /^(Added|Run|Tests|Answer|Needed|Needs from you):/i.test(t)) {
      listing = false;
      continue;
    }
    const n = listing && /^(?:[-*\u2022]\s*)?(?:criterion\s*|#)?(\d{1,3})\b/i.exec(t);
    if (n) named.add(Number(n[1]));
  }
  return named;
}
const whole = new Set([...storyIds.keys()].filter((id) => storyOf(id) === id));
for (const [id, name] of done) {
  const text = doneTexts.get(id);
  const count = criteriaCount(text);
  if (!tested.has(id) || count === 0 || whole.has(id)) continue;
  const named = namedCriteria(text, id);
  for (const t of storyIds.keys()) if (storyOf(t) === id && t !== id) named.add(Number(t.slice(id.length + 1)));
  const missing = Array.from({ length: count }, (_, i) => i + 1).filter((n) => !named.has(n));
  const past = [...named].filter((n) => n > count).sort((a, b) => a - b);
  const list = (ns) => (ns.length === 1 ? `${ns[0]}` : `${ns.slice(0, -1).join(', ')} and ${ns[ns.length - 1]}`);
  if (past.length) {
    add('SR-21', `stories/done/${name}: lists ${count} acceptance criteria, but ${id}-${past[0]} names criterion ${past[0]}: the list has changed since its tests were written. A criterion keeps its number once it has a test: put the list back as it was (a dropped criterion stays, answered "drop"), or renumber its tests and notes with it.`);
  } else if (missing.length) {
    const noted = text.includes('---- IMPLEMENTED');
    add('SR-21', `stories/done/${name}: ${missing.length === 1 ? 'criterion' : 'criteria'} ${list(missing)} of its ${count}${noted ? ` named nowhere: neither a test (${id}-<n>) nor a Not implemented line in its IMPLEMENTED note.` : ', and it has no IMPLEMENTED note.'} Implement each as ${id}-<n>, or add a Not implemented line for it: <n> <the criterion>: <what is needed>.`);
  }
}

// ---- SR-22: one element, one name ---------------------------------------------------------------------

// Two constants of one Elements file with the same locator, one of them in a YOURS block: one element under
// two names (SIGN_IN_BUTTON and LOGIN_BUTTON, added by two stories). A locator is its first string.
for (const f of files('cypress/support/pages').filter((p) => p.endsWith('Elements.ts'))) {
  const byLocator = new Map();
  const yoursOf = new Map();
  let yours = false;
  for (const line of read(f).split(/\r?\n/)) {
    if (line.includes('==== YOURS (')) yours = true;
    if (line.includes('==== END YOURS (')) yours = false;
    const m = /^\s*([A-Z][A-Z0-9_]*):.*?(['"`])((?:\\.|(?!\2).)*)\2/.exec(line);
    if (!m) continue;
    const locator = m[3].replace(/^xpath=/, '').trim();
    const earlier = byLocator.get(locator);
    if (earlier === undefined) {
      byLocator.set(locator, m[1]);
      yoursOf.set(m[1], yours);
    } else if (yours || yoursOf.get(earlier)) {
      add('SR-22', `${f}: ${earlier} and ${m[1]} are one element under two names (both "${locator}"). Keep one, and point every use of the other at it (search the specs and pages for its name).`);
    }
  }
}

// ---- the report --------------------------------------------------------------------------------------

const idOf = (p) => p.slice(1, p.indexOf(' '));
const tierOf = (p) => (p.includes(`] ${ADVISORY}`) ? 'advisory' : TIERS[idOf(p)]);
const failing = problems.filter((p) => tierOf(p) !== 'advisory');
const warnings = problems.filter((p) => tierOf(p) === 'advisory');
const section = (tier, note) => {
  const found = problems.filter((p) => tierOf(p) === tier);
  return `\n## ${tier} (${note}): ${found.length}\n\n${found.length ? found.map((p) => `- ${p}`).join('\n') : 'None.'}\n`;
};
mkdirSync(join(root, 'cypress'), { recursive: true });
writeFileSync(join(root, 'cypress/rules-report.md'), `advisory warnings: ${warnings.length}\n\n# The suite's rules, this run\n${section('hard', 'these fail the check')}${section('story', 'these fail the check')}${section('advisory', 'warnings: the run goes on')}`);
warnings.forEach((p) => console.log(`   WARNING ${p} (advisory: SUITE-RULES.md)`));
if (failing.length) {
  console.log(`The suite's rules are broken (SUITE-RULES.md: why each exists, and how to fix it; cypress/rules-report.md):`);
  failing.forEach((p, i) => console.log(`  ${i + 1}. ${p}`));
  process.exit(1);
}
console.log(`The suite's rules: ${warnings.length ? `none broken, ${warnings.length} warning${warnings.length === 1 ? '' : 's'}` : `all ${Object.keys(RULES).length} hold`} (${relative(root, root) || '.'}).`);
